import os,sys,json,time,traceback
sys.path.insert(0,'/opt/tools')
import numpy as np
from PIL import Image,ImageDraw
from scipy.spatial.transform import Rotation as R
from rcb_client import Robot,EpisodeOver
r=Robot()
spec=r.spec()
json.dump(spec,open('/app/output/spec.json','w'),indent=2)
count=0
obs=None

def record(res):
 global obs,count
 obs=res; count+=1
 res.save(f'/app/runs/{count:03d}')
 ims=[]
 for cam,img in res.last.items():
  im=Image.fromarray(img).resize((448,448)); d=ImageDraw.Draw(im);d.text((5,5),cam,fill=(255,0,0));ims.append(im)
 canvas=Image.new('RGB',(448*len(ims),448))
 for i,im in enumerate(ims):canvas.paste(im,(448*i,0))
 canvas.save('/app/output/latest.jpg')
 json.dump(res.meta,open('/app/output/latest_meta.json','w'),indent=2)
 print('RESULT',count,json.dumps({k:v for k,v in res.meta.items() if k not in ['proprio','cameras']}),flush=True)
 print('PROPRIO',json.dumps(dict(zip(res.meta['proprio']['layout'],res.meta['proprio']['now']))),flush=True)
 return res

def observe(seconds=0):return record(r.get_obs(seconds=seconds,depth=True))
def act(a,dt=.1,note=''):
 return record(r.submit('joint_position',a,dt=dt,depth=True,note=note))
def ee(a,note=''):
 return record(r.submit('ee_pose',a,depth=True,note=note))
def now():return dict(zip(obs.meta['proprio']['layout'],obs.meta['proprio']['now']))
def row():
 d=now();return np.array([d.get(n,0.) for n in spec['action_types']['joint_position']['layout']],float)
def pixels(cam,uv):
 K=np.array(obs.meta['cameras'][cam]['intrinsic_cv']);E=np.array(obs.meta['cameras'][cam]['extrinsic_cv']);
 uv=np.array(uv).reshape(-1,2);z=np.array([obs.last_depth[cam][int(v),int(u)] for u,v in uv]);
 p=(np.linalg.inv(K)@np.column_stack([uv,np.ones(len(uv))]).T).T*z[:,None]
 return (p-E[:,3])@E[:,:3]
def poses():
 d=now();return {a:np.array([d[f'{a}_eef_{n}'] for n in ['x','y','z','qx','qy','qz','qw']]) for a in ['left','right']}
print('READY',flush=True)
observe()
for line in sys.stdin:
 try:
  cmd=json.loads(line);exec(cmd['code'],globals());print('COMMAND_DONE',flush=True)
 except EpisodeOver as e:print('EPISODE_OVER',str(e),flush=True)
 except Exception as e:
  traceback.print_exc()
  if '500' in str(e) or '502' in str(e) or 'Connection' in str(type(e)):
   print('RECOVERING',flush=True);r.wait_ready();print('STATUS',r.status(),flush=True);observe()
